CREATE TABLE IF NOT EXISTS specialties ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Name" varchar(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS experts ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Name" varchar(160) NOT NULL, "Capacity" integer NOT NULL CHECK ("Capacity" > 0), "IsActive" boolean NOT NULL DEFAULT TRUE, "LastAssignedAt" timestamptz NULL);
CREATE INDEX IF NOT EXISTS ix_experts_is_active ON experts ("IsActive");
CREATE TABLE IF NOT EXISTS expert_specialties ("ExpertId" integer NOT NULL REFERENCES experts("Id") ON DELETE CASCADE, "SpecialtyId" integer NOT NULL REFERENCES specialties("Id") ON DELETE CASCADE, PRIMARY KEY("ExpertId", "SpecialtyId"));
CREATE TABLE IF NOT EXISTS requests ("Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "RequestKey" varchar(200) NOT NULL UNIQUE, "SpecialtyId" integer NOT NULL REFERENCES specialties("Id") ON DELETE RESTRICT, "Priority" integer NOT NULL, "Status" integer NOT NULL, "AssignedExpertId" integer NULL REFERENCES experts("Id") ON DELETE RESTRICT, "CreatedAt" timestamptz NOT NULL, "AssignedAt" timestamptz NULL, "ClosedAt" timestamptz NULL);
CREATE INDEX IF NOT EXISTS ix_requests_status_priority_created_at ON requests ("Status", "Priority", "CreatedAt");
CREATE INDEX IF NOT EXISTS ix_requests_assigned_expert_id_status ON requests ("AssignedExpertId", "Status");
CREATE TABLE IF NOT EXISTS assignment_history ("Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "RequestId" bigint NOT NULL REFERENCES requests("Id") ON DELETE RESTRICT, "ExpertId" integer NOT NULL REFERENCES experts("Id") ON DELETE RESTRICT, "AssignedAt" timestamptz NOT NULL, "UnassignedAt" timestamptz NULL);
CREATE INDEX IF NOT EXISTS ix_assignment_history_request_id ON assignment_history ("RequestId");
